interface Payment {
    void pay();
}
class CardPayment implements Payment {
    public void pay() { System.out.println("Card paid"); }
}
class OrderService {
    private final Payment payment;
    OrderService(Payment payment) {
        this.payment = payment;
    }
    void checkout() { payment.pay(); }
}
// Inside main:
OrderService service = new OrderService(new CardPayment());
service.checkout();
